{
  "missing_information": [
    {
      "category": "actor",
      "gap": "It is unclear who is responsible for creating the meeting summary — a designated note-taker, the meeting organizer, an AI tool, or a participant.",
      "why_it_matters": "Identifying the actor determines whether the summarization step is manual, semi-automated, or fully automated, which directly affects automation potential."
    },
    {
      "category": "input",
      "gap": "The source material for the summary is not defined — it could be handwritten notes, a transcript, a recording, or slide decks.",
      "why_it_matters": "The format and availability of input data determines which summarization tools or AI models can be applied and how much preprocessing is needed."
    },
    {
      "category": "output",
      "gap": "The required structure and content of the summary is unspecified — e.g., whether it must include action items, decisions made, attendees, or follow-up deadlines.",
      "why_it_matters": "A defined output template is necessary to automate generation and to ensure consistency across meetings."
    },
    {
      "category": "decision",
      "gap": "There is no information about how the recipient list for the email is determined — whether it is fixed, role-based, or decided ad hoc after each meeting.",
      "why_it_matters": "Dynamic recipient selection requires either manual intervention or a rule/data source to automate distribution correctly."
    },
    {
      "category": "manual_effort",
      "gap": "It is unknown whether the summary goes through a review or approval step before being sent, and who performs that review.",
      "why_it_matters": "An approval gate adds latency and a human dependency that must be modeled and potentially streamlined or bypassed in automation."
    },
    {
      "category": "frequency",
      "gap": "The volume and regularity of meetings requiring this workflow is not stated — e.g., how many meetings per day or week trigger this process.",
      "why_it_matters": "Frequency determines the scale of automation benefit and influences infrastructure and tooling decisions."
    },
    {
      "category": "system",
      "gap": "The systems used for email distribution and any existing meeting or collaboration platforms are not identified.",
      "why_it_matters": "Integration constraints depend on which platforms are in use; automation feasibility differs greatly depending on available APIs and connectors."
    },
    {
      "category": "exception",
      "gap": "There is no mention of what happens when a summary cannot be produced — e.g., if the recording is missing, notes are incomplete, or the responsible person is unavailable.",
      "why_it_matters": "Exception handling paths must be defined to build a robust automated workflow that does not silently fail."
    }
  ],
  "clarification_questions": [
    {
      "id": "Q1",
      "question": "Who is currently responsible for producing the meeting summary — a specific role such as the meeting organizer or a designated note-taker — and is any tool or automated transcription service already involved in that step?",
      "targets": ["actor", "system"]
    },
    {
      "id": "Q2",
      "question": "What source material is used to create the summary — for example, live notes, an audio or video recording, an auto-generated transcript, or shared slides?",
      "targets": ["input"]
    },
    {
      "id": "Q3",
      "question": "Is there a required format or template for the summary, such as mandatory sections for decisions made, action items with owners, or follow-up deadlines?",
      "targets": ["output"]
    },
    {
      "id": "Q4",
      "question": "How is the email recipient list determined after each meeting — is it fixed to all attendees, manually curated by the organizer, or driven by a rule such as role or team membership?",
      "targets": ["decision"]
    },
    {
      "id": "Q5",
      "question": "Does the summary need to be reviewed or approved by anyone before the email is sent, and if so, who performs that review and what is the typical turnaround time?",
      "targets": ["manual_effort", "risk_or_approval"]
    },
    {
      "id": "Q6",
      "question": "Approximately how many meetings per week trigger this summarization and email workflow, and is the volume consistent or does it vary significantly?",
      "targets": ["frequency"]
    }
  ]
}
